"""Billing for donations. Rate lookups are billed, so the charge is remembered."""
import rates


class DonationBill:
    def __init__(self):
        self._donations = []
        self._charge = None

    def add(self, donation):
        """Add one donation to the bill."""
        self._donations.append(donation)

    def charge(self):
        """Return the total charge: pounds times the rate for each donation's donor.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.pounds * rates.rate_for(x.donor) for x in self._donations)
        return self._charge


def group_by_donor(donations):
    """Return a dict from donor to the list of donations with that donor."""
    groups = {}
    for x in donations:
        groups.setdefault(x.donor, []).append(x)
    return groups


def donor_names(donations):
    """Return the distinct donor values, in first-seen order."""
    names = []
    for x in donations:
        if x.donor not in names:
            names.append(x.donor)
    return names
